async function messageChart(){const root=layout();root.append(A.filterPanel());const metrics=node('div','metric-grid');metrics.id='chartMetrics';root.append(metrics);const c=card('消息占比'),chart=node('div','chart');chart.id='messageChart';c.append(chart);root.append(c);try{chartData=await fetch('data/content/message-chart-'+A.tenant+'.json').then(r=>{if(!r.ok)throw Error();return r.json();});}catch{const total=A.num(A.source.text.split('\n').filter(s=>/^[\d,]+$/.test(s.trim())).pop());chartData={total,points:[],captured_at:A.source.capturedAt};}if(chartData.sourceKind==='mock'){A.source.state='mock';document.querySelector('.badge').textContent='演示样本';}drawChart();}
